library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all; use work.bb_util_pkg.all;
entity bbq_moving_average_core is generic(SAMPLE_WIDTH:positive:=16;WINDOW:positive:=8;SIGNED_MODE:boolean:=true);port(clk,rst_n:in std_logic;sample_in:in std_logic_vector(SAMPLE_WIDTH-1 downto 0);sample_valid:in std_logic;average_out:out std_logic_vector(SAMPLE_WIDTH-1 downto 0);average_valid:out std_logic);end;
architecture rtl of bbq_moving_average_core is constant SW:positive:=SAMPLE_WIDTH+clog2(WINDOW)+1;type mem_t is array(0 to WINDOW-1)of signed(SAMPLE_WIDTH downto 0);signal mem:mem_t:=(others=>(others=>'0'));signal idx:natural range 0 to WINDOW-1:=0;signal count:natural range 0 to WINDOW:=0;signal sum:signed(SW-1 downto 0):=(others=>'0');signal a:std_logic_vector(SAMPLE_WIDTH-1 downto 0):=(others=>'0');signal v:std_logic:='0';begin average_out<=a;average_valid<=v;process(clk)variable incoming,old:signed(SAMPLE_WIDTH downto 0);variable ns:signed(SW-1 downto 0);variable denom:positive;begin if rising_edge(clk)then v<='0';if rst_n='0'then mem<=(others=>(others=>'0'));idx<=0;count<=0;sum<=(others=>'0');a<=(others=>'0');elsif sample_valid='1'then if SIGNED_MODE then incoming:=resize(signed(sample_in),SAMPLE_WIDTH+1);else incoming:=signed('0'&sample_in);end if;old:=mem(idx);ns:=sum+resize(incoming,SW)-resize(old,SW);mem(idx)<=incoming;sum<=ns;if idx=WINDOW-1 then idx<=0;else idx<=idx+1;end if;if count<WINDOW then count<=count+1;denom:=count+1;else denom:=WINDOW;end if;a<=std_logic_vector(resize(ns/to_signed(denom,SW),SAMPLE_WIDTH));v<='1';end if;end if;end process;end architecture;
